/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"edits": [["C40", "C50"], ["500\u00d7500", "600\u00d7600"], ["40", "50"]]};
  phases([[0,14],[14,30],[30,52],[52,80]]);
  v.pickO = lin([[0,0],[2,1],[11,1],[14,0]]); v.pickT = 'translateY(' + lin([[0,16],[2,0]]).toFixed(1) + 'px)';
  for (var i = 0; i < 4; i++) v['pk'+i] = p >= 3 + i * 1.8 ? 1 : 0;
  var xin = lin([[15,0],[20,1]]);
  v.xO = xin * out; v.xT = 'translateX(' + (40 * (1 - xin)).toFixed(1) + 'px)';
  v.eO = lin([[14,0],[16,1],[26,1],[29,0]]);
  v.iO = lin([[52,0],[54,1],[64,1],[67,0]]);
  D.edits.forEach(function (e, k) {
    var s = 32 + k * 6, typed = p >= s + 2.5;
    var partial = e[1].slice(0, Math.max(0, Math.min(e[1].length, Math.floor((p - s) / 2.5 * e[1].length))));
    v['x'+k] = p < s ? e[0] : (typed ? e[1] : (partial.length ? partial : e[0]));
    v['xh'+k] = (p >= s && p < 97) ? out : 0;
    var rs = 56 + k * 2;
    v['r'+k] = p >= rs ? e[1] : e[0];
    v['rh'+k] = (p >= rs && p < 97) ? out * (p < rs + 1 ? 1 : 0.85) : 0;
  });
  v.upd = (p >= 63 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
